SELECT CASE WHEN balance >= 79000 THEN 'high' WHEN balance >= 31000 THEN 'mid' ELSE 'low' END AS balance_bucket, ROUND((100 * SUM(CASE WHEN account_type = 'SAVINGS' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_savings FROM accounts GROUP BY CASE WHEN balance >= 79000 THEN 'high' WHEN balance >= 31000 THEN 'mid' ELSE 'low' END HAVING pct_savings < 46 ORDER BY pct_savings DESC, balance_bucket
